/// <summary>
/// CB627_TMSEngineProcessingTOCreation
/// Class to proceede with the creation process for TMS engine
/// </summary>
[METTMSEngineExecutionModeAttribute(METTMSEngineExecutionMode::TransferOrderPickinglist)]
internal final class METTMSEngineTransferOrderProccess_Pickinglist extends METTMSEngineOrderProccess
{
}

Method.Source:
/// <summary>
/// Gets the execution mode enum <t>METTMSEngineExecutionMode</t>
/// </summary>
/// <returns>Execution mode</returns>
public METTMSEngineExecutionMode getExecutionMode()
{
    METTMSEngineExecutionMode ret = METTMSEngineExecutionMode::TransferOrderPickinglist;

    return ret;
}

/// <summary>
/// Sets the field values of shipment table buffer <t>METTMSShipmentTable</t>
/// </summary>
/// <param name = "_tmsShipmentTable">Shipment table buffer</param>
protected void setTMSShipmentFields(METTMSShipmentTable _tmsShipmentTable)
{
    METInventTransferTableExt inventTransferTableExt = headerContract.getExtensionTable();

    super(_tmsShipmentTable);

    _tmsShipmentTable.DestinationCustomer = inventTransferTableExt.InternalCustomer;
    _tmsShipmentTable.DestinationWarehouse = headerContract.parmSourceRecord().InventLocationTo;
}

/// <summary>
/// error message
/// </summary>
/// <returns>error txt</returns>
protected ErrorTxt errorMessage()
{
    return strFmt("@MET:TMSEngineTransferOrderProcessCreation", headerContract.parmSourceRecord().OrderId);
}

/// <summary>
/// Override - Validate to exclude an orders.
/// </summary>
/// <returns>true if valdidation successful; otherwise, false</returns>
protected boolean validateOrderExcluded()
{
    METTMSEngineHeaderTransferOrderContract transferOrderContract;

    if (headerContract is METTMSEngineHeaderTransferOrderContract)
    {
        transferOrderContract = headerContract as METTMSEngineHeaderTransferOrderContract;
        return transferOrderContract.isOrderExcludedTransferType();
    }

    return true;
}
